export type Company = { id: string; name: string; ticker: string | null; displayOrder: number; recency?: 'mid' | 'high' };
export type RunStatus = 'queued' | 'running' | 'completed' | 'failed';
export type RunPhase = 'queued' | 'fanout' | 'relations' | 'healthcare_gate' | 'stopped' | 'finance' | 'completed' | 'failed';
export type Run = { id: string; companyId: string | null; mode: 'seed' | 'delta'; status: RunStatus; phase: RunPhase; startedAt: string | null; finishedAt: string | null; error: string | null; counts: Record<string, number> };
export type RunEvent = { id: string; runId?: string; phase: RunPhase; kind: 'phase' | 'tool_call' | 'tool_result' | 'error'; tool: string | null; summary: string | null; input?: Record<string, unknown>; output?: Record<string, unknown>; createdAt: string };
export type QueuedRun = { id: string; status: 'queued' };
export type GraphEntity = { id: string; entityType: string; label: string; sourceId: string | null };
export type GraphRelationship = { id: string; fromEntityId: string; toEntityId: string; relationshipType: string; evidenceDocumentId: string | null };
export type GraphNeighborhood = { nodes: GraphEntity[]; edges: GraphRelationship[] };
export type GraphDocument = { id: string; provider: string; providerId: string; url: string | null; publishedAt: string | null; excerpt: string };
export type GraphEntityDetail = {
  entity: GraphEntity & { externalId: string | null; properties: Record<string, unknown> };
  company: Company | null;
  document: GraphDocument | null;
  relationships: Array<GraphRelationship & { evidenceUrl: string | null; confidence: number }>;
  evidence: GraphDocument[];
};
export type ServiceHealth = { status: 'ok' | 'degraded'; postgres: 'connected' | 'unavailable'; neo4j: 'connected' | 'unavailable' };

const companies: Company[] = [
  ['moderna', 'Moderna', 'MRNA'], ['pfizer', 'Pfizer', 'PFE'], ['eli-lilly', 'Eli Lilly', 'LLY'], ['jnj', 'Johnson & Johnson', 'JNJ'], ['roche', 'Roche', 'RHHBY'], ['abbvie', 'AbbVie', 'ABBV'], ['merck', 'Merck & Co.', 'MRK'], ['novartis', 'Novartis', 'NVS'], ['amgen', 'Amgen', 'AMGN'], ['sanofi', 'Sanofi', 'SNY']
].map(([id, name, ticker], displayOrder) => ({ id, name, ticker, displayOrder, recency: displayOrder % 2 === 0 ? 'high' : 'mid' }));
const runs: Run[] = companies.map((c, i) => ({
  id: `run-${c.id}`,
  companyId: c.id,
  mode: 'delta',
  status: i === 0 ? 'completed' : 'running',
  phase: i === 0 ? 'completed' : 'healthcare_gate',
  startedAt: null,
  finishedAt: null,
  error: null,
  counts: {},
}));

const API_BASE_URL = (((import.meta as ImportMeta & { env?: { VITE_API_BASE_URL?: string } }).env?.VITE_API_BASE_URL) ?? '').replace(/\/$/, '');
const apiUrl = (path: string) => `${API_BASE_URL}${path}`;

async function requestJson<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(apiUrl(path), { ...init, headers: { 'Content-Type': 'application/json', ...(init?.headers ?? {}) } });
  if (!response.ok) throw new Error(`Request failed (${response.status}) for ${path}`);
  return response.json() as Promise<T>;
}

async function json<T>(url: string): Promise<T> {
  const response = await fetch(apiUrl(url));
  if (!response.ok) throw new Error((await response.json().catch(() => null))?.error ?? `Request failed (${response.status})`);
  return response.json() as Promise<T>;
}

export async function listCompanies() { try { const response = await fetch(apiUrl('/companies')); if (response.ok) return await response.json() as Company[]; } catch {} return companies; }
export async function listCompanyRuns(companyId: string) { try { const response = await fetch(apiUrl(`/companies/${companyId}/agent-runs`)); if (response.ok) return await response.json() as Run[]; } catch {} return runs.filter((r) => r.companyId === companyId); }
export async function createAgentRun(companyId: string, mode: 'seed' | 'delta' = 'delta') { return requestJson<QueuedRun>('/runs', { method: 'POST', body: JSON.stringify({ companyId, mode }) }); }
export async function getRun(runId: string) { return requestJson<Run>(`/runs/${encodeURIComponent(runId)}`); }
export async function getRunEvents(runId: string) { return requestJson<RunEvent[]>(`/runs/${encodeURIComponent(runId)}/events`); }

export async function getKnowledgeGraph(filters: {
  companyId?: string;
  nodeId?: string;
  entityTypes?: string[];
  relationshipTypes?: string[];
  query?: string;
  limit?: number;
}): Promise<GraphNeighborhood> {
  const params = new URLSearchParams();
  if (filters.companyId) params.set('companyId', filters.companyId);
  if (filters.nodeId) params.set('nodeId', filters.nodeId);
  if (filters.entityTypes?.length) params.set('entityTypes', filters.entityTypes.join(','));
  if (filters.relationshipTypes?.length) params.set('relationshipTypes', filters.relationshipTypes.join(','));
  if (filters.query) params.set('query', filters.query);
  if (filters.limit) params.set('limit', String(filters.limit));
  return json<GraphNeighborhood>(`/knowledge-graph?${params}`);
}

export const getGraphEntityDetail = (id: string) => json<GraphEntityDetail>(`/knowledge-graph/entities/${encodeURIComponent(id)}`);
export const getServiceHealth = () => json<ServiceHealth>('/health');

export type GraphAskFilter = {
  allCompanies?: boolean;
  companyTicker?: string | null;
  companyName?: string | null;
  entityTypes?: string[];
  relationshipTypes?: string[];
  labelQuery?: string | null;
};

export type GraphSqlResult = {
  question: string;
  sql: string;
  explanation: string;
  rows: Record<string, unknown>[];
  rowCount: number;
  graphFilter?: GraphAskFilter;
};

export async function askGraphSql(question: string): Promise<GraphSqlResult> {
  const response = await fetch(apiUrl('/knowledge-graph/sql'), {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ question }),
  });
  const payload = await response.json().catch(() => null) as (GraphSqlResult & { error?: string }) | null;
  if (!response.ok) throw new Error(payload?.error ?? `SQL agent failed (${response.status})`);
  return payload as GraphSqlResult;
}

import { Router } from 'express';
import { createRepositoriesFromEnv } from '@cala/db';
import { listSourceDocuments } from '@cala/db/src/repositories/source-documents.js';
import { listDevelopments } from '@cala/db/src/repositories/developments.js';
import { databaseEnabled, listRuns, listRunsPersisted } from '@cala/db/src/repositories/runs.js';
import { listPeopleForCompany } from '@cala/db/src/repositories/people.js';

export const companiesRouter = Router();
companiesRouter.get('/', async (_req, res) => res.json(await createRepositoriesFromEnv().companies.list()));
companiesRouter.post('/', async (req, res) => {
  const { name, ticker = null } = req.body ?? {};
  if (typeof name !== 'string' || !name.trim() || (ticker !== null && typeof ticker !== 'string')) {
    return res.status(400).json({ error: 'name and ticker are required' });
  }
  return res.status(201).json(await createRepositoriesFromEnv().companies.create({ name: name.trim(), ticker }));
});
companiesRouter.get('/:id', async (req, res) => {
  const company = await createRepositoriesFromEnv().companies.get(req.params.id);
  const runs = databaseEnabled() ? await listRunsPersisted(req.params.id) : listRuns(req.params.id);
  return company ? res.json({ ...company, latestRun: runs[0] ?? null }) : res.status(404).json({ error: 'company not found' });
});
companiesRouter.get('/:id/agent-runs', async (req, res) =>
  res.json(databaseEnabled() ? await listRunsPersisted(req.params.id) : listRuns(req.params.id)),
);
companiesRouter.get('/:id/timeline', (req, res) =>
  res.json(
    listSourceDocuments(req.params.id).map((document) => ({
      id: document.id,
      kind: 'source_document',
      provider: document.provider,
      title: document.normalizedText.slice(0, 120),
      occurredAt: document.publishedAt ?? document.createdAt,
    })),
  ),
);
companiesRouter.get('/:id/people', (req, res) => res.json(listPeopleForCompany(req.params.id)));
companiesRouter.get('/:id/developments', (req, res) => res.json(listDevelopments(req.params.id)));

import { Router } from 'express';
import { createRepositoriesFromEnv } from '@cala/db';
import { listRunEvents, listRunEventsPersisted } from '@cala/db/src/repositories/run-events.js';
import { databaseEnabled } from '@cala/db/src/repositories/runs.js';

export const runsRouter = Router();
export let enqueueRun = (_runId: string): void => {};
export function setEnqueueRun(fn: (runId: string) => void): void {
  enqueueRun = fn;
}
runsRouter.post('/', async (req, res) => {
  const { companyId, mode } = req.body ?? {};
  if (typeof companyId !== 'string' || (mode !== 'seed' && mode !== 'delta')) {
    return res.status(400).json({ error: "companyId and mode ('seed' or 'delta') are required" });
  }
  const run = await createRepositoriesFromEnv().runs.create({ companyId, mode });
  enqueueRun(run.id);
  return res.status(202).json({ id: run.id, status: 'queued' });
});
runsRouter.get('/:id', async (req, res) => {
  const run = await createRepositoriesFromEnv().runs.get(req.params.id);
  return run ? res.json(run) : res.status(404).json({ error: 'run not found' });
});
runsRouter.get('/:id/events', async (req, res) => {
  const run = await createRepositoriesFromEnv().runs.get(req.params.id);
  if (!run) return res.status(404).json({ error: 'run not found' });
  return res.json(databaseEnabled() ? await listRunEventsPersisted(run.id) : listRunEvents(run.id));
});

import type { Company, CompanyRecency } from '@cala/contracts';
import { randomUUID } from 'node:crypto';
import { asc, eq } from 'drizzle-orm';
import { db } from '../client.js';
import { companies as companiesTable } from '../schema.js';

function recencyFor(displayOrder: number): CompanyRecency {
  return displayOrder % 2 === 0 ? 'high' : 'mid';
}

const companies: Company[] = [];
export function listCompanies(): Company[] { return [...companies].sort((a, b) => a.displayOrder - b.displayOrder || a.name.localeCompare(b.name)); }
export function createCompany(input: { name: string; ticker: string | null }): Company {
  const displayOrder = companies.length;
  const company: Company = { id: randomUUID(), name: input.name, ticker: input.ticker, displayOrder, recency: recencyFor(displayOrder), createdAt: new Date().toISOString() };
  companies.push(company); return company;
}
export function resetCompanies(): void { companies.length = 0; }

export function databaseEnabled(): boolean { return Boolean(process.env.DATABASE_URL); }
function fromRow(row: typeof companiesTable.$inferSelect): Company {
  const recency = row.recency === 'high' ? 'high' : 'mid';
  return { id: row.id, name: row.name, ticker: row.ticker, displayOrder: row.displayOrder, recency, createdAt: row.createdAt.toISOString() };
}
export async function listCompaniesPersisted(): Promise<Company[]> { return (await db.select().from(companiesTable).orderBy(asc(companiesTable.displayOrder), asc(companiesTable.name))).map(fromRow); }
export async function getCompanyPersisted(id: string): Promise<Company | undefined> { const [row] = await db.select().from(companiesTable).where(eq(companiesTable.id, id)).limit(1); return row ? fromRow(row) : undefined; }
export async function createCompanyPersisted(input: { name: string; ticker: string | null }): Promise<Company> {
  const displayOrder = (await listCompaniesPersisted()).length;
  const [row] = await db.insert(companiesTable).values({ name: input.name, ticker: input.ticker, displayOrder, recency: recencyFor(displayOrder) }).returning();
  return fromRow(row);
}

